sys_script_email.script:
(function runMailScript(current, template, email, email_action, event) {
    /* PTAG Hub: base URL for every notification link. Property-driven so
       the template set survives instance moves (I6 carry-over fix). */
    template.print(gs.getProperty('x_snc_ptag_engage.portal_base_url', 'https://astrodev.service-now.com'));
})(current, template, email, email_action, event);
